export type ExtraTaskItem = { title: string; prompt: string; notes: string; ccss: string; grade: string };
export const EXTRA_TASKS: Record<string, ExtraTaskItem[]> = {
  "rekenreks": [
    { title: "Teen numbers as 10 and more", prompt: "Show 16 as a full row of 10 and 6 more on the next row. Say it as ten and six, then write 10 + 6 = 16.", notes: "Teen numbers should be read as 10 plus a single digit. If a child counts to 16 bead by bead, point to the full row and ask them to trust it as ten.", ccss: "1.NBT.B.2b", grade: "1" },
    { title: "Make 9 three ways", prompt: "Show 9 on one row, then on two rows, then with the cover hiding some beads. Record each way you made it.", notes: "Seeing the same total in different arrangements builds flexibility. Ask which way makes 9 easiest to see at a glance and why.", ccss: "1.OA.C.6", grade: "1" },
    { title: "Count back from 18", prompt: "Start at 18 across two rows. Slide beads back one row at a time to subtract 5. Where do you land?", notes: "Counting back across the ten boundary is the hard part. Encourage landing on 10 first, then counting back the rest.", ccss: "1.OA.C.5", grade: "1" },
    { title: "Doubles plus one", prompt: "Show double 7 on two equal rows, then add one extra bead. What addition have you built?", notes: "This is the near-double strategy in concrete form. Name it after children discover the extra bead changes 14 to 15.", ccss: "2.OA.B.2", grade: "2" },
    { title: "Missing part to 15", prompt: "Show 8 on the top row. How many more beads are needed to reach 15 in total? Build the missing part underneath.", notes: "Missing-addend problems prepare for subtraction as finding a difference, not just taking away.", ccss: "1.OA.D.8", grade: "1" },
    { title: "Even or odd check", prompt: "Build 12, then 13. In each case, can the beads pair up exactly across two rows with none left over?", notes: "Pairing is a physical test for even and odd. The leftover bead for odd numbers should be pointed out explicitly.", ccss: "2.OA.C.3", grade: "2" },
    { title: "Three numbers to 20", prompt: "Use three rows to show 6 + 5 + 4. Find a pair that makes 10 first, then add the last row.", notes: "Hunting for a ten first is a key mental strategy. Let children rearrange the order and notice the total stays the same.", ccss: "2.OA.B.2", grade: "2" },
    { title: "Compare two rows", prompt: "Show 7 on one row and 9 on another. How many more is 9 than 7? Show the difference with beads.", notes: "Difference is visible as the unmatched beads when rows are lined up. Language matters: say how many more, not just take away.", ccss: "1.OA.A.1", grade: "1" },
    { title: "Build 20, hide 10", prompt: "Fill two full rows to make 20, then cover one whole row. How many are hidden and how do you know without counting?", notes: "A full covered row must be 10 because every row holds 10. This moves children from counting to reasoning about structure.", ccss: "K.NBT.A.1", grade: "K" },
    { title: "Subtract to the benchmark", prompt: "Show 14. Slide beads back to land exactly on 10, then slide back 3 more. What did you subtract in total?", notes: "Breaking subtraction at the ten benchmark mirrors bridging in addition and makes larger subtractions manageable.", ccss: "2.NBT.B.5", grade: "2" },
    { title: "Five-wise counting", prompt: "Push beads in groups of 5 only. Count 5, 10, 15, 20 as each group lands. What pattern do you hear?", notes: "Counting in fives is anchored by the red groups of five. Connect the spoken pattern to the visual groups.", ccss: "2.NBT.A.2", grade: "2" },
    { title: "Story beads: birds", prompt: "There were 9 birds, then 6 more landed. Show the story on two rows and write the matching number sentence.", notes: "Stories give addition a meaning beyond beads. Ask children to tell the story back before they write symbols.", ccss: "1.OA.A.1", grade: "1" },
    { title: "Half of 10, half of 20", prompt: "Show half of 10 on one row, then half of 20 using two rows. How are the two halves related?", notes: "Half of 20 uses the same five-bead group in each row. This plants the idea that halves scale with the whole.", ccss: "2.G.A.3", grade: "2" },
  ],
  "two-color-counters": [
    { title: "Make 10 in a frame", prompt: "Fill a ten-frame with yellow counters to make 10, then flip 3 to red. What addition and subtraction does the frame show now?", notes: "Flipping keeps the total at 10 while changing the parts. Children should read both 7 + 3 and 10 - 3 from the same frame.", ccss: "K.OA.A.4", grade: "K" },
    { title: "Integer climb", prompt: "Start at -4 with red counters. Add 7 yellow counters, pairing zeros as you go. Where do you finish?", notes: "Pairing as you add prevents a messy pile and shows why -4 + 7 is positive 3, not 11.", ccss: "7.NS.A.1b", grade: "7" },
    { title: "Two colours, one total", prompt: "Put 11 counters out, some yellow and some red, with no zero pairs. If the value is 5, how many of each colour are there?", notes: "This is a small system in disguise: total counters and net value together fix both colours. Let children trial and adjust.", ccss: "7.NS.A.1", grade: "7" },
    { title: "Probability counters", prompt: "Put 4 yellow and 6 red counters in a bag model on the mat. If you pick one without looking, which colour is more likely?", notes: "Use counters to model chance language: more likely, less likely, equally likely. Keep numbers small so the comparison is clear.", ccss: "7.SP.C.5", grade: "7" },
    { title: "Groups of counters", prompt: "Make 4 groups of 3 yellow counters. How many in total? Now rearrange them as 3 groups. What changed and what stayed the same?", notes: "Rearranging groups shows commutativity of multiplication concretely before symbols are introduced.", ccss: "3.OA.B.5", grade: "3" },
    { title: "Negative take away", prompt: "Start with 2 red counters and add zero pairs until you can take away 5 yellow. Show -2 - 5 and the result.", notes: "Taking away counters you do not have is why zero pairs exist. Narrate each added pair as adding zero, so the value does not change.", ccss: "7.NS.A.1c", grade: "7" },
    { title: "Fraction of a set", prompt: "Lay out 12 counters. Make 1/3 of them red and the rest yellow. How many are red? Try 1/4 of the same set.", notes: "The whole is the set of 12, not a single shape. Dividing the set into equal groups is the key move.", ccss: "3.NF.A.1", grade: "3" },
    { title: "Pattern with counters", prompt: "Build a growing pattern: 1 yellow, 2 red, 3 yellow, 4 red. What comes next and how many counters by stage 5?", notes: "Recording stage totals in a table helps children see the pattern rule rather than just extending shapes.", ccss: "4.OA.C.5", grade: "4" },
    { title: "Balance the mat", prompt: "On a part-part-whole mat, put 8 in the whole and 3 in one part. Fill the other part and write the subtraction it shows.", notes: "The missing part is found by counting on from 3 to 8. Connect that counting-on to subtraction explicitly.", ccss: "1.OA.B.4", grade: "1" },
    { title: "Zero pair detective", prompt: "A mat shows 9 yellow and 9 red counters mixed together. What is the value and how can you prove it without counting all of them?", notes: "Pairing is the proof. Children should physically match counters until none are left unpaired.", ccss: "7.NS.A.1a", grade: "7" },
    { title: "Double and halve", prompt: "Show 6 yellow counters. Double the amount, then halve it back. What operations did your hands just do?", notes: "Doubling and halving with objects makes inverse operations visible. Ask for the number sentences afterwards.", ccss: "3.OA.B.6", grade: "3" },
    { title: "Counters for data", prompt: "Sort a mixed pile by colour and line the groups up as a bar. Which group is longer by how many counters?", notes: "A counter bar is a first bar graph. Aligning the start line matters for a fair comparison.", ccss: "2.MD.D.10", grade: "2" },
    { title: "Add unlike signs", prompt: "Show +6 and -9 together. Pair zeros and read the result. Explain why the answer takes the sign of the larger group.", notes: "The leftover colour tells the sign. This image stays with children when they later meet rules for adding integers.", ccss: "7.NS.A.1b", grade: "7" },
  ],
  "linking-cubes": [
    { title: "Train lengths", prompt: "Build trains of 4, 7 and 10 cubes. Order them shortest to longest and find how much longer the longest is than the shortest.", notes: "Comparing lengths by direct alignment is early measurement. The difference is counted in cube units.", ccss: "1.MD.A.2", grade: "1" },
    { title: "Measure with cubes", prompt: "Use a cube train to measure a pencil and a book in cube units. Which object needed more cubes and by how many?", notes: "Non-standard units are honest measurement if cubes are placed end to end with no gaps. Name the unit every time.", ccss: "2.MD.A.1", grade: "2" },
    { title: "Make a metre of cubes", prompt: "Join sticks of 10 until you have 100 cubes in a line. How many sticks did you use and what does the line represent?", notes: "Ten sticks of ten makes one hundred visible as a length. This links counting, grouping and place value.", ccss: "2.NBT.A.2", grade: "2" },
    { title: "Cube trains for 15", prompt: "Break a 15-cube train into a ten-stick and the rest. Write 15 as 10 + 5, then try a different split.", notes: "The ten-plus split is the teen number structure. Other splits are valid but the ten split is the most useful.", ccss: "1.NBT.B.2b", grade: "1" },
    { title: "Volume by cubes", prompt: "Build a 3 by 2 by 2 box shape from cubes. How many cubes fill it? Count layer by layer.", notes: "Layer counting introduces volume as repeated area. Children should say 6 per layer, 2 layers, 12 in total.", ccss: "5.MD.C.4", grade: "5" },
    { title: "Symmetry tower", prompt: "Build half a tower, then mirror it with cubes in a second colour. Where is the mirror line?", notes: "Building the mirror image cube by cube makes symmetry a construction task, not just a spotting task.", ccss: "4.G.A.3", grade: "4" },
    { title: "Estimate then count", prompt: "Grab a handful of cubes, estimate how many, then snap them into tens and count exactly. How close was your estimate?", notes: "Estimating before counting gives counting a purpose. Grouping in tens makes the exact count reliable.", ccss: "2.NBT.A.3", grade: "2" },
    { title: "Equal groups", prompt: "Make 5 towers of 4 cubes. Write the repeated addition and the multiplication for the total.", notes: "Towers must be exactly equal or the multiplication does not apply. Checking equality is part of the task.", ccss: "3.OA.A.1", grade: "3" },
    { title: "Cube fractions", prompt: "Build a stick of 8 cubes with 2 colours. What fraction is each colour? Change the stick to 12 and repeat.", notes: "Fraction of a length model: the stick is the whole. Keep the whole explicit in every sentence.", ccss: "3.NF.A.1", grade: "3" },
    { title: "Perimeter with cubes", prompt: "Lay cubes around the edge of a rectangle card. How many cubes go around? How is that different from covering it?", notes: "Around versus covering separates perimeter from area in the most physical way possible.", ccss: "3.MD.D.8", grade: "3" },
    { title: "Number bond tower", prompt: "Build a tower of 9 using three colours. Record the three parts and write two additions the tower shows.", notes: "Three-part bonds extend the usual two-part work and prepare for adding three numbers.", ccss: "1.OA.A.3", grade: "1" },
    { title: "Scaling a model", prompt: "Build a tiny chair from 6 cubes, then build a version twice as tall. How many cubes and what stayed in proportion?", notes: "Scaling is informal here: the point is noticing which dimensions doubled and discussing the effect.", ccss: "6.RP.A.1", grade: "6" },
    { title: "Missing cubes", prompt: "Build a 10-cube stick, hide some cubes under a hand, show 4. How many are hidden? Prove it with a second stick.", notes: "Hidden part problems are subtraction in context. The checking stick makes the reasoning public.", ccss: "1.OA.D.8", grade: "1" },
  ],
  "color-tiles": [
    { title: "Border pattern", prompt: "Tile the border of a 5 by 5 square in one colour and fill the inside in another. How many tiles of each colour?", notes: "Border is 16, interior is 9. Children often double-count corners, so marking corners first helps.", ccss: "4.MD.A.3", grade: "4" },
    { title: "Odd and even areas", prompt: "Build rectangles with areas 7, 8, 9 and 10 tiles. Which areas make a complete rectangle with both sides longer than 1?", notes: "Prime areas only make a 1-wide strip. This is factor thinking in tile form, without naming primes yet.", ccss: "4.OA.B.4", grade: "4" },
    { title: "Tile a letter", prompt: "Use tiles to make the first letter of your name on the grid. Count the tiles and estimate its perimeter in tile edges.", notes: "Free building with a count attached keeps it mathematical. Perimeter here counts exposed edges only.", ccss: "3.MD.C.6", grade: "3" },
    { title: "Halves of rectangles", prompt: "Build a 4 by 6 rectangle. Cover exactly half with a second colour in two different ways.", notes: "Half can be split by rows, columns or a staircase. All covers must total 12 tiles.", ccss: "3.G.A.2", grade: "3" },
    { title: "Multiplication grid", prompt: "Build a 6 by 7 rectangle, then split it into 6 by 5 and 6 by 2. Show how the split helps you work out 6 x 7.", notes: "Splitting one factor is the distributive property with tiles. The two smaller rectangles must add to the original area.", ccss: "3.OA.B.5", grade: "3" },
    { title: "Tile symmetry quilt", prompt: "Make a 4 by 4 quilt tile design with two lines of symmetry. Swap designs with a partner and check each other's.", notes: "Checking a partner's symmetry is harder than making your own and surfaces small mismatches quickly.", ccss: "4.G.A.3", grade: "4" },
    { title: "Growing border", prompt: "Start with 1 tile, add a border to make 3 by 3, then 5 by 5. Record the totals: what is the pattern?", notes: "Totals are odd squares 1, 9, 25. The border added each time grows by 8, which strong finishers can explain.", ccss: "4.OA.C.5", grade: "4" },
    { title: "Fraction wall tiles", prompt: "Make a row of 12 tiles. Cover 1/2, then below it cover 1/3 and 1/4 in new rows lined up at the left. What do you notice?", notes: "Lining up fractions of the same whole lets children compare sizes directly and spot equivalences like 2/4.", ccss: "4.NF.A.1", grade: "4" },
    { title: "Area challenge 20", prompt: "Use 20 tiles to make a rectangle with the smallest possible perimeter. Then make the largest perimeter. Record both.", notes: "Compact shapes minimise perimeter, long thin shapes maximise it. Same area, very different borders.", ccss: "4.MD.A.3", grade: "4" },
    { title: "Tile number line", prompt: "Lay 20 tiles in a row as a number line. Mark 0, 5, 10, 15, 20 with a second colour. Jump from 6 to 17 and count the jump.", notes: "A tiled line makes intervals countable. The jump length is a difference, counted in tiles.", ccss: "2.MD.B.6", grade: "2" },
    { title: "Cover without gaps", prompt: "Cover a 6 by 4 card completely, then cover an L-shaped card. How many tiles for each and how did you check for gaps?", notes: "Tessellation language belongs here: no gaps, no overlaps. The L-shape forces row-by-row thinking.", ccss: "3.MD.C.7a", grade: "3" },
    { title: "Percent tiles", prompt: "Build a 10 by 10 square. Cover 35 tiles in one colour. What percent is covered and what percent is not?", notes: "A hundred grid is the percent model: each tile is 1 percent. The uncovered 65 percent completes the picture.", ccss: "6.RP.A.3c", grade: "6" },
    { title: "Ratio tiles", prompt: "Show the ratio 2 blue to 3 red with tiles, then double the row and then triple it. What stays the same?", notes: "Scaling a ratio keeps the relationship while totals grow. Children should say for every 2 blue there are 3 red.", ccss: "6.RP.A.1", grade: "6" },
  ],
  "hundred-board": [
    { title: "Skip count by 3s", prompt: "Highlight multiples of 3 to 30. Say the numbers as you go, then continue the pattern to 60 from memory.", notes: "The board shows why the pattern drifts diagonally: 3 does not divide 10, so each row shifts.", ccss: "2.NBT.A.2", grade: "2" },
    { title: "Prime hunt intro", prompt: "Cover every multiple of 2, 3 and 5 except the numbers themselves. Which numbers under 30 stay uncovered?", notes: "This is a gentle sieve. Uncovered numbers include primes and 1, which sparks a good discussion about what prime means.", ccss: "4.OA.B.4", grade: "4" },
    { title: "Add 9 trick", prompt: "Cover 34. Add 9 by moving down one row and back one. Try it for 56 and 82 and explain why it works.", notes: "Adding 10 then subtracting 1 is the strategy; the board move makes it unforgettable.", ccss: "2.NBT.B.5", grade: "2" },
    { title: "Number neighbours", prompt: "Cover a number and name its four neighbours: left, right, above, below. What operation finds each one?", notes: "Neighbours are plus or minus 1 and plus or minus 10. Naming the operation turns board geography into arithmetic.", ccss: "1.NBT.C.5", grade: "1" },
    { title: "Between tens", prompt: "Cover 73. Which two tens does it sit between and which ten is it closer to? Show the distances on the board.", notes: "Distance to each ten is counted in steps. Closer ten is the rounding answer, with a reason attached.", ccss: "3.NBT.A.1", grade: "3" },
    { title: "Square numbers", prompt: "Highlight 1, 4, 9, 16, 25 and 36. Describe where they sit and the gaps between them.", notes: "Gaps grow by odd numbers 3, 5, 7, 9, 11. Children who spot that have found real structure.", ccss: "4.OA.C.5", grade: "4" },
    { title: "Two-digit detective", prompt: "A covered number is 10 more than 45 and 1 less than 56. Find it, uncover and check both clues.", notes: "Both clues point to 55. Solving from clues reverses the usual direction of board work.", ccss: "2.NBT.A.3", grade: "2" },
    { title: "Counting in 25s", prompt: "Start at 0 and highlight every 25 to 100. What quarters pattern do you see on the board?", notes: "25, 50, 75, 100 land in a clear rhythm tied to quarters of 100. Link to money quarters if children know them.", ccss: "3.NBT.A.2", grade: "3" },
    { title: "Odd even checkerboard", prompt: "Colour all even numbers. What pattern appears and how can it prove 47 is odd without counting?", notes: "Evens form columns, odds sit between them. Position alone can decide parity once the pattern is trusted.", ccss: "2.OA.C.3", grade: "2" },
    { title: "Subtract across rows", prompt: "Cover 52. Subtract 23 by moving up two rows and right three. Where do you land and why does that work?", notes: "Up rows subtract tens, right adds ones. Decomposing 23 into 20 and 3 is the strategy being built.", ccss: "2.NBT.B.7", grade: "2" },
    { title: "Hundred board race", prompt: "Start at 1. A partner calls add 10, add 1 or subtract 10. Follow the moves and say where you land after five calls.", notes: "Oral movement games build fluent board navigation. Keep pace brisk and celebrate accurate landings.", ccss: "1.NBT.C.4", grade: "1" },
    { title: "Decimal neighbours", prompt: "In decimal mode, cover 3.6. Say 0.1 more, 0.1 less, 1 more and 1 less, then uncover to check.", notes: "The same neighbour logic works with tenths. The unit changed, the structure did not.", ccss: "5.NBT.B.7", grade: "5" },
    { title: "Missing row", prompt: "Hide a whole row of the board. Say the row's numbers from memory by describing its pattern.", notes: "A row is one ten repeated in the ones place pattern 0 to 9. Describing it beats memorising it.", ccss: "2.NBT.A.3", grade: "2" },
  ],
  "base-ten-blocks": [
    { title: "Build and read 2,048", prompt: "Build 2,048, read it aloud in words, then write it in expanded form beside the blocks.", notes: "Expanded form should mirror the blocks: 2000 + 40 + 8, with an empty hundreds place that still needs its zero in standard form.", ccss: "4.NBT.A.2", grade: "4" },
    { title: "Add with one regroup", prompt: "Build 157 and 86. Combine and regroup once. Which column forced the regroup?", notes: "Only the ones column overflows here. Naming the column that regroups focuses attention on why carrying happens.", ccss: "2.NBT.B.7", grade: "2" },
    { title: "Subtract with breaking", prompt: "Build 203 and take away 58. Break a flat and a rod as needed. How many breaks did you make?", notes: "Two breaks are needed, which is why zeros in subtraction cause trouble. Each break should be narrated before taking away.", ccss: "3.NBT.A.2", grade: "3" },
    { title: "Multiply by 10", prompt: "Build 34, then build ten times as much. What changed in every column?", notes: "Every piece moves one place larger. This is the place value effect of multiplying by 10, not just adding a zero.", ccss: "5.NBT.A.2", grade: "5" },
    { title: "Area model 13 x 12", prompt: "Use rods and units to build a 13 by 12 rectangle outline and fill its four regions. Add the regions for the product.", notes: "Regions are 100, 20, 30 and 6, totalling 156. The model shows where partial products come from.", ccss: "4.NBT.B.5", grade: "4" },
    { title: "Compare two builds", prompt: "Build 1,205 and 1,250 side by side. Which is larger and which column decides it?", notes: "The tens column decides because thousands and hundreds tie. Comparing column by column from the left is the method.", ccss: "4.NBT.A.2", grade: "4" },
    { title: "Decimal add 1.7 + 0.85", prompt: "In decimal mode build 1.7 and 0.85, combine and regroup hundredths into tenths. Record the sum.", notes: "Regrouping works the same to the right of the decimal point. Children must name the new unit before building.", ccss: "5.NBT.B.7", grade: "5" },
    { title: "Round with blocks", prompt: "Build 468. Show with blocks why it rounds to 470 to the nearest 10 and 500 to the nearest 100.", notes: "Distance decides: 468 is 2 from 470 and 32 from 500 at hundred scale. Blocks make the two scales visible in turn.", ccss: "3.NBT.A.1", grade: "3" },
    { title: "Factors with flats", prompt: "Use 12 rods to build rectangles. Which widths work exactly? List the factor pairs of 12 you found.", notes: "Rectangles that close exactly are factor pairs. A width of 5 leaves a gap, which is the point: not every width works.", ccss: "4.OA.B.4", grade: "4" },
    { title: "Thousand cube build", prompt: "Build 999, then add one unit. Regroup step by step until a single cube remains. Say each regroup aloud.", notes: "999 + 1 cascades through every place. The final cube is worth 1000, the chant ten of these make one of those holds at each step.", ccss: "2.NBT.B.8", grade: "2" },
    { title: "Divide by sharing", prompt: "Build 96 with rods and units and share it equally into 4 groups. How much is in each group?", notes: "Sharing place value pieces may need a break: 9 rods do not share by 4 until one is broken into units.", ccss: "4.NBT.B.6", grade: "4" },
    { title: "Zero in the middle", prompt: "Build 505 and 550. How do the blocks differ and why does the zero matter in each number?", notes: "In 505 the zero holds the tens place, in 550 it holds the ones. Same digit, different job depending on position.", ccss: "2.NBT.A.3", grade: "2" },
    { title: "Estimate the build", prompt: "Show a build of flats, rods and units for three seconds, hide it, and estimate the total. Then reveal and check.", notes: "Quick looks force children to use place value chunks rather than counting units. Estimates within 10 percent are strong.", ccss: "3.NBT.A.2", grade: "3" },
  ],
  "place-value-disks": [
    { title: "Disk race to a million", prompt: "Start with 9 disks of 100,000. Add one more and regroup. Keep going: how many regroups to reach 1,000,000 from 900,000 in steps of 100,000?", notes: "One regroup at the end turns ten 100,000 disks into a million disk. Large numbers obey the same ten-for-one rule.", ccss: "4.NBT.A.1", grade: "4" },
    { title: "Write it three ways", prompt: "Build 63,402. Write it in standard form, word form and expanded form. Which form matches the disks most closely?", notes: "Expanded form mirrors disks one to one. Word form is where the empty thousands place most often gets dropped.", ccss: "4.NBT.A.2", grade: "4" },
    { title: "Divide disks by 10", prompt: "Build 4,500. Move every disk one place right. What number remains and what division did you perform?", notes: "Moving right divides by 10. Repeating the move shows repeated division and prepares for decimals.", ccss: "5.NBT.A.2", grade: "5" },
    { title: "Subtract across zeros", prompt: "Build 1,000 and take away 1 disk of 1. Break the thousand disk step by step until you can take 1 away. What is left?", notes: "The cascade 1000 to 999 is the classic hard case. Disks show every break, so the answer 999 is earned, not guessed.", ccss: "4.NBT.B.4", grade: "4" },
    { title: "Decimal compare", prompt: "Build 0.72 and 0.7 with disks. Which is greater and which column proves it?", notes: "Tenths tie, hundredths decide. Children who say 0.72 is smaller because it has more digits need this exact comparison.", ccss: "5.NBT.A.3b", grade: "5" },
    { title: "Multiply disks", prompt: "Build 213. Triple every disk count. Regroup where a column passes ten and read the product.", notes: "Tripling disks is 213 x 3 with the algorithm made visible. Regrouping after tripling mirrors carrying.", ccss: "4.NBT.B.5", grade: "4" },
    { title: "Smallest and largest", prompt: "With disks for 3, 0, 7 and 5, build the largest 4-digit number and the smallest. How far apart are they?", notes: "Largest 7,530, smallest 3,057 because zero cannot lead. The difference needs a subtraction with breaks, good practice in context.", ccss: "4.NBT.A.2", grade: "4" },
    { title: "Thousandths build", prompt: "Build 0.063. Which places are empty, and what happens if you add one 0.001 disk seven times?", notes: "Adding seven thousandths fills the hundredths place after regrouping: 0.070. Small disks, same regrouping rule.", ccss: "5.NBT.B.7", grade: "5" },
    { title: "Population talk", prompt: "A town has 48,209 people. Build it, then show what happens to the disks if 10,000 more people arrive.", notes: "Adding a ten-thousand disk changes one column only. Place value keeps big real numbers manageable.", ccss: "4.NBT.B.4", grade: "4" },
    { title: "Disk fractions link", prompt: "Build 0.5, 0.50 and 0.500 with disks. Are the values equal? What extra disks appear?", notes: "Trailing zeros add empty-value disks pairs that regroup to the same amount. Equality of decimals becomes visible.", ccss: "5.NBT.A.3a", grade: "5" },
    { title: "Round the disks", prompt: "Build 76,850. Round it to the nearest thousand by looking at the disks. Which disk decides?", notes: "The hundreds disk decides: 8 hundreds rounds the thousands up to 77,000. The deciding disk should be pointed to.", ccss: "4.NBT.A.3", grade: "4" },
    { title: "Break in two ways", prompt: "Build 34. Break it into tens and ones in two different ways, for example 3 tens and 4 ones, then 2 tens and 14 ones.", notes: "Flexible breaking is the heart of mental subtraction. Both forms must be read aloud to prove they equal 34.", ccss: "3.NBT.A.2", grade: "3" },
    { title: "Missing disk mystery", prompt: "A build shows 5 hundred-thousands, 2 tens and 4 ones, total 500,024 is claimed. Is the claim right? Fix it if not.", notes: "The build is 500,024 only if the other places are truly empty. Checking claims against disks builds verification habits.", ccss: "4.NBT.A.2", grade: "4" },
  ],
  "cuisenaire-rods": [
    { title: "Rod algebra: r + w", prompt: "If red is 2 and white is 1, build trains that show 2 + 2 + 2 using rods only. What single rod matches the train?", notes: "Three reds match dark green 6. Repeated addition with rods is multiplication waiting for its name.", ccss: "3.OA.A.1", grade: "3" },
    { title: "Measure the gap", prompt: "Lay orange against a line of rods that is too long. Find the rod that measures the overshoot exactly.", notes: "Overshoot is a difference measured in rods. Exact fit is the success test, estimation is not enough.", ccss: "2.MD.A.1", grade: "2" },
    { title: "Fraction of a rod", prompt: "If brown is 1 whole, which rod is 1/2, which is 1/4 and which is 1/8? Prove each by laying rods alongside.", notes: "Halving repeatedly: brown 8, purple 4, red 2, white 1. The chain shows unit fractions nested inside each other.", ccss: "3.NF.A.2", grade: "3" },
    { title: "Rod equations", prompt: "Build a train: yellow + red = dark green + white. Check both sides match in length, then write the equation.", notes: "Equal lengths are equal values. Children should slide a ruler along both ends to verify before writing equals.", ccss: "1.OA.D.7", grade: "1" },
    { title: "Decimals with orange as 1", prompt: "Let orange be 1. Give the value of every rod as a decimal and order the rods by value.", notes: "Each unit is a tenth when orange is the whole, so values run 0.1 to 1.0 in rod order. The staircase becomes a decimal scale.", ccss: "5.NBT.A.3", grade: "5" },
    { title: "Commutative trains", prompt: "Build 3 + 5 as light green then yellow, and 5 + 3 as yellow then light green. What is the same and what is different?", notes: "Order changes, length does not. That observation is commutativity, earned by building rather than told.", ccss: "1.OA.B.3", grade: "1" },
    { title: "Rod word problem", prompt: "A ribbon is one orange and one red long. A second ribbon is one blue and one light green. Are they the same length?", notes: "Both total 12. Comparing sums through lengths gives children a checking strategy for word problems.", ccss: "2.OA.A.1", grade: "2" },
    { title: "Square numbers with rods", prompt: "Build squares using rods: 2 by 2, 3 by 3, 4 by 4 in rod units. How many white rods would fill each square?", notes: "Areas 4, 9, 16 in unit rods. Building squares from rods links length multiplication to area.", ccss: "3.MD.C.7b", grade: "3" },
    { title: "Missing rod", prompt: "Build a train the length of blue using yellow and one mystery rod hidden by your hand. Partner finds the mystery rod's value.", notes: "The mystery rod is 4, purple, because 9 - 5 = 4. Hiding creates a genuine need to subtract.", ccss: "2.OA.B.2", grade: "2" },
    { title: "Ratio rods", prompt: "Lay red and light green as a pair, then build the same relationship three times longer. What rods show the scaled ratio?", notes: "Scaling 2 to 3 gives 6 to 9, dark green to blue. Length ratios stay honest when both rods scale together.", ccss: "6.RP.A.1", grade: "6" },
    { title: "Rod perimeter", prompt: "Make a rectangle from two orange rods and two yellow rods. What is its perimeter in white-rod units?", notes: "Perimeter is 10 + 5 + 10 + 5 = 30 units. Travelling around the shape with rods makes perimeter a journey.", ccss: "3.MD.D.8", grade: "3" },
    { title: "Negative steps", prompt: "Start at orange length 10 on a number line of rods. Step back a blue rod. Where are you and what subtraction shows it?", notes: "Landing at 1 shows 10 - 9. Large steps back are less scary when the landing rod is visible.", ccss: "2.NBT.B.5", grade: "2" },
    { title: "Equivalence trains", prompt: "Find two different two-rod trains that both match black 7. Record them as equations and check a third train.", notes: "7 splits as 6 + 1, 5 + 2, 4 + 3. Listing all splits systematically is early algebraic completeness.", ccss: "1.OA.C.6", grade: "1" },
  ],
  "fraction-circles": [
    { title: "Thirds and ninths talk", prompt: "Cover a whole with thirds, then predict how many ninths would cover one third. Test your prediction with pieces.", notes: "Three ninths cover a third, which is why ninths are not in the set: children must reason, not just place. Accept drawn ninths as evidence.", ccss: "4.NF.A.1", grade: "4" },
    { title: "More than a whole", prompt: "Build 5/4 using quarter pieces and a second whole outline. Write it as a mixed number.", notes: "Five quarters need a second circle, which is exactly why mixed numbers exist. Name 1 and 1/4 after building.", ccss: "4.NF.B.3b", grade: "4" },
    { title: "Compare to a half", prompt: "For each piece size, decide if one piece is more or less than half a circle. Sort the pieces into two piles.", notes: "Only the whole and halves reach a half; every other single piece is less. The sorting makes the benchmark physical.", ccss: "3.NF.A.3d", grade: "3" },
    { title: "Add unlike pieces", prompt: "Add 1/2 and 1/4 by covering. Why did the sum need pieces of one size to be described exactly?", notes: "The sum is 3/4, found by trading the half for two quarters. Trading to a common size is the seed of common denominators.", ccss: "5.NF.A.1", grade: "5" },
    { title: "Percent pie", prompt: "Cover 40 percent of a circle. Switch labels and write the fraction and decimal for the same cover.", notes: "40 percent is 2/5 or 0.4. Switching labels on an unchanged cover is the strongest equivalence demonstration.", ccss: "6.RP.A.3c", grade: "6" },
    { title: "Eighths exploration", prompt: "Build 3/8, then add 2/8, then 3/8 more. When do you pass a whole and by how much?", notes: "The total reaches 8/8 exactly at the end, passing through 5/8. Counting in eighths aloud builds fraction fluency.", ccss: "4.NF.B.3a", grade: "4" },
    { title: "Fraction of a turn", prompt: "Rotate a quarter piece through a full turn in steps. How many quarter turns make a half turn and a full turn?", notes: "Fractions of a turn link fractions to angles: a quarter turn is 90 degrees, which children meet in geometry.", ccss: "4.MD.C.5", grade: "4" },
    { title: "Leftover pieces", prompt: "Cover a whole as closely as you can using only fifths, without going over. What fraction is left uncovered?", notes: "Four fifths cover 4/5, leaving 1/5. Five fifths would be exact, so discuss why the leftover is what it is.", ccss: "4.NF.B.3", grade: "4" },
    { title: "Order the pieces", prompt: "Take one piece of each size and order them smallest to largest. Explain the pattern in the denominators.", notes: "Bigger denominator, smaller piece, because the whole is cut into more parts. Saying the why matters more than the order.", ccss: "3.NF.A.3d", grade: "3" },
    { title: "Twelfths clock", prompt: "Use twelfths pieces to show 20 minutes, 30 minutes and 45 minutes on a circle as a clock face.", notes: "Twelfths are clock fractions: each piece is 5 minutes. This connects two tools children already know separately.", ccss: "3.MD.A.1", grade: "3" },
    { title: "Equivalent cover", prompt: "Cover 2/3 of a circle, then cover the same amount using sixths only. Record both sentences.", notes: "2/3 equals 4/6, visible as an exact cover. Require edges to align before accepting the equivalence.", ccss: "4.NF.A.1", grade: "4" },
    { title: "Decimal switch challenge", prompt: "Build an amount, switch labels to decimal, and have a partner rebuild it from your decimal description only.", notes: "Rebuilding from a description tests whether the decimal truly names the same amount as the pieces.", ccss: "5.NBT.A.3", grade: "5" },
    { title: "Half and quarter mix", prompt: "Cover a whole using only halves and quarters, in as many ways as you can. Record each way as a sum.", notes: "Possibilities include 1/2 + 1/4 + 1/4 and four quarters. Systematic searching can be modelled by fixing the number of halves first.", ccss: "4.NF.B.3d", grade: "4" },
  ],
  "fraction-tiles": [
    { title: "Wall hunt: 3/4", prompt: "On the fraction wall, find every fraction equal to 3/4 up to twelfths. Record the family.", notes: "6/8 and 9/12 join 3/4. The wall edge alignment is the evidence children should cite.", ccss: "4.NF.A.1", grade: "4" },
    { title: "Compare with benchmarks", prompt: "Place 5/8 and 2/3 against a half benchmark tile. Which is closer to 1 and how does the wall show it?", notes: "Both pass a half; 2/3 leaves a smaller gap to 1. Gap-to-benchmark reasoning is the target strategy.", ccss: "4.NF.A.2", grade: "4" },
    { title: "Add thirds and sixths", prompt: "Add 1/3 and 1/6 with tiles. Trade pieces until the sum can be named in one denominator.", notes: "Trading a third for two sixths gives 3/6, which is a half. Trading is the physical form of finding common denominators.", ccss: "5.NF.A.1", grade: "5" },
    { title: "Mixed number build", prompt: "Build 2 and 3/5 using whole and fifth tiles. Then build the same amount as an improper fraction.", notes: "13/5 needs thirteen fifth tiles, which children can count along the row. Both names describe one amount.", ccss: "4.NF.B.3b", grade: "4" },
    { title: "Fraction times whole", prompt: "Show 3 groups of 2/5 tiles. What is 3 x 2/5 and how do the tiles show the regrouping past 1?", notes: "Six fifths regroup as 1 and 1/5. The overflow past the whole tile is where the mixed number appears.", ccss: "4.NF.B.4", grade: "4" },
    { title: "Order unlike fractions", prompt: "Order 1/4, 3/8, 1/2 and 5/8 using the wall. Explain each step of your ordering.", notes: "The wall settles order by length. Children should still verbalise: 3/8 sits between 1/4 and 1/2 because its length does.", ccss: "4.NF.A.2", grade: "4" },
    { title: "Subtract from a whole", prompt: "Start with a whole tile. Take away 3/10 using tenth tiles. What remains and how can you check it?", notes: "7/10 remains, checked by adding back to the whole. Inverse checking should become a habit.", ccss: "5.NF.A.1", grade: "5" },
    { title: "Decimal tiles", prompt: "Switch labels to decimal. Build 0.7 and 0.25 side by side. Which row of tiles did each need and why?", notes: "0.7 uses tenths, 0.25 needs hundredths thinking modelled with tiles as quarters of tenths discussion. Precision of language matters.", ccss: "5.NBT.A.3", grade: "5" },
    { title: "Half of a half", prompt: "Cover a half tile exactly with quarter tiles, then cover a quarter with eighths. What pattern is emerging?", notes: "Each halving doubles the denominator. The pattern 2, 4, 8 prepares for fraction multiplication by a half.", ccss: "5.NF.B.4", grade: "5" },
    { title: "Tile story problem", prompt: "A pizza is cut in eighths. You eat 3 slices, your friend eats 2. Build the story and write the fraction left.", notes: "5/8 eaten, 3/8 left. Stories anchor tile work; ask children to act the eating by removing tiles.", ccss: "4.NF.B.3d", grade: "4" },
    { title: "Equivalent rename", prompt: "Rename 4/10 in lowest terms using tiles. Why is 2/5 the same amount?", notes: "Covering 4 tenth tiles exactly with 2 fifth tiles proves the rename. Lowest terms means no smaller tile covers exactly.", ccss: "4.NF.A.1", grade: "4" },
    { title: "Gap fractions", prompt: "Place a half and a third with a gap between them and a whole. What fraction fills the gap exactly?", notes: "The gap is 1/6, found by trading both to sixths. Gap problems are subtraction disguised as building.", ccss: "5.NF.A.1", grade: "5" },
    { title: "Percent tiles switch", prompt: "Build 3/5, switch labels to percent, and read the amount. Build 60 percent a second way to check.", notes: "3/5 is 60 percent. Building it from percent-labelled pieces confirms the switch did not change the amount.", ccss: "6.RP.A.3c", grade: "6" },
  ],
  "number-lines": [
    { title: "Round on the line", prompt: "Mark 348 on a 300 to 400 line. Which hundred is it nearer and how does its position show it?", notes: "Position between hundreds shows nearness directly: 348 sits just before the halfway point of 350.", ccss: "3.NBT.A.1", grade: "3" },
    { title: "Decimal steps", prompt: "On a 0 to 1 line with 0.1 intervals, plot 0.3, 0.7 and 0.9. Jump from 0.3 to 0.9 and name the jump.", notes: "The jump is +0.6, six tenths steps. Counting steps in tenths reinforces decimal place value.", ccss: "5.NBT.B.7", grade: "5" },
    { title: "Temperature line", prompt: "Use a -20 to 30 line for temperatures. Plot -5, 0 and 18. How much warmer is 18 than -5?", notes: "The distance across zero is 23 degrees. Crossing zero must be counted in two parts, 5 and 18.", ccss: "6.NS.C.7", grade: "6" },
    { title: "Fraction between fractions", prompt: "On a 0 to 1 line split in eighths, find a fraction between 1/4 and 1/2. Defend your choice.", notes: "3/8 sits between 2/8 and 4/8. Renaming to eighths is the move that makes between-ness visible.", ccss: "4.NF.A.2", grade: "4" },
    { title: "Jump strategy 48 + 25", prompt: "Start at 48. Jump 20, then jump to the next ten, then the rest. Record the three jumps.", notes: "48 + 20 = 68, +2 = 70, +3 = 73. Landing on a ten mid-addition is the bridging strategy on a line.", ccss: "2.NBT.B.5", grade: "2" },
    { title: "Elapsed on a line", prompt: "Mark 2:30 and 5:00 as points 2.5 and 5 on a time line. How long between them in hours?", notes: "Lines turn clock time into distance: 2.5 hours. This prepares for decimal time calculations.", ccss: "3.MD.A.1", grade: "3" },
    { title: "Multiply as jumps", prompt: "Show 4 jumps of 6 on a 0 to 30 line. Where do you land and what multiplication have you drawn?", notes: "Equal jumps are multiplication as repeated addition. Unequal jumps would break the model, which is worth discussing.", ccss: "3.OA.A.1", grade: "3" },
    { title: "Negative ordering", prompt: "Plot -7, -2, -9 and 0. Order them and explain why -9 is smallest even though 9 is biggest.", notes: "On the line, left means smaller. Distance from zero is size of the number, position gives the order for negatives.", ccss: "6.NS.C.7a", grade: "6" },
    { title: "Estimate the point", prompt: "Hide labels on a 0 to 100 line. A point sits about three quarters along. Estimate it, then reveal and refine.", notes: "Anchoring on halves and quarters is the estimation strategy. Refining after reveal teaches calibration.", ccss: "3.NBT.A.1", grade: "3" },
    { title: "Difference as distance", prompt: "Plot 23 and 41. Measure the gap. Now plot -5 and 13 and measure again. What is the same about the method?", notes: "Both gaps are distances: 18 in each case. Subtraction as distance works across zero too.", ccss: "7.NS.A.1c", grade: "7" },
    { title: "Halves and quarters", prompt: "On a 0 to 2 line with quarter intervals, plot 1/2, 3/4, 1 and 1/4, and 7/4. Which points coincide with whole numbers?", notes: "Only the whole number points coincide; improper fractions sit beyond 1, which is the point of including 7/4.", ccss: "3.NF.A.2b", grade: "3" },
    { title: "Inequality line", prompt: "Shade or mark all numbers greater than 4 and less than 9 on a line. Test 5, 9 and 4: which belong?", notes: "Endpoints are excluded here, a subtle idea. Testing boundary values makes the convention discussable.", ccss: "6.EE.B.8", grade: "6" },
    { title: "Scale the line", prompt: "Plot 150, 300 and 450 on a 0 to 600 line with interval 50. Why does the interval choice matter?", notes: "Interval choice is scale choice. Too small an interval crowds labels, too large loses precision.", ccss: "3.MD.B.4", grade: "3" },
  ],
  "bar-models": [
    { title: "Two-step bar", prompt: "A shop sells 15 red pens and twice as many blue pens. Build the bar and find the total pens.", notes: "The blue bar is two units of 15, total 45. Two-step problems need the hidden step found first, and the bar exposes it.", ccss: "3.OA.D.8", grade: "3" },
    { title: "Fraction bar: leftovers", prompt: "A bar shows a whole pizza of 8 slices with 3 eaten. Model the fraction eaten and the fraction left.", notes: "The bar splits into 8 equal parts; eaten 3/8, left 5/8. Equal parts are non-negotiable for fraction bars.", ccss: "4.NF.B.3", grade: "4" },
    { title: "Comparison difference", prompt: "Bar A is 42, bar B is 27. Build both and mark the difference segment. What equation finds it?", notes: "Aligning left edges makes the difference a visible segment: 42 - 27 = 15. Comparison bars beat key-word hunting.", ccss: "2.OA.A.1", grade: "2" },
    { title: "Ratio scale up", prompt: "Juice to water is 1 to 4. Build the bar, then scale to a total of 25 parts. How much juice?", notes: "Each part becomes 5, so juice is 5 and water 20. Scaling keeps the 1 to 4 relationship intact.", ccss: "6.RP.A.3", grade: "6" },
    { title: "Money bar", prompt: "You save 12 dollars a week. Build a bar for 6 weeks and find the total saved.", notes: "Equal segments of 12, six times, is multiplication as a bar. Labelling each segment prevents the common weeks-times mix-up.", ccss: "3.OA.A.1", grade: "3" },
    { title: "Unknown start", prompt: "After giving away 9 stickers, you have 14 left. Build a bar with the start unknown and find how many you began with.", notes: "Start-unknown problems are the hardest addition type. The bar shows the whole must be 14 + 9 = 23.", ccss: "2.OA.A.1", grade: "2" },
    { title: "Percent bar", prompt: "Build a bar for 100 percent and shade 30 percent of it. If the whole is 50, what amount is shaded?", notes: "30 percent of 50 is 15. A percent bar anchors percent to a whole of 100 first, then rescales.", ccss: "6.RP.A.3c", grade: "6" },
    { title: "Groups bar", prompt: "There are 5 boxes with the same number of eggs, 30 eggs in total. Build the bar and find eggs per box.", notes: "Five equal unknown segments totalling 30 gives 6 per box. This is division as finding an unknown factor.", ccss: "3.OA.B.6", grade: "3" },
    { title: "Change bar", prompt: "A jacket costs 68 dollars and is reduced by 17 dollars. Model the change and find the new price.", notes: "A bar with a removed segment models reduction more clearly than a comparison pair here. New price 51 dollars.", ccss: "4.MD.A.2", grade: "4" },
    { title: "Sum and difference", prompt: "Two numbers add to 50 and differ by 10. Build comparison bars and find both numbers.", notes: "Removing the difference segment leaves two equal parts of 40, so 20 and 30. Bars turn a puzzle into a method.", ccss: "3.OA.D.8", grade: "3" },
    { title: "Rate bar", prompt: "A car travels 60 miles in 1 hour. Build a bar for 3.5 hours at the same rate.", notes: "Unit rate first: each hour segment is 60, so 3.5 hours is 210 miles. Half segments are allowed and should be labelled.", ccss: "6.RP.A.3b", grade: "6" },
    { title: "Fraction remainder", prompt: "A bar of 36 is split so 2/3 is used. Build it and find how much remains.", notes: "One third is 12, used is 24, remains 12. Finding the unit fraction first is the reliable route.", ccss: "5.NF.B.4", grade: "5" },
    { title: "Three-part whole", prompt: "A class of 28 has 12 girls, 9 boys who walk and the rest who ride. Build a three-part bar and find the riders.", notes: "Three parts must sum to the whole: riders are 7. Checking the sum closes the task.", ccss: "2.OA.A.1", grade: "2" },
  ],
  "money": [
    { title: "Make a dollar", prompt: "Make exactly 1 dollar using only dimes, then only nickels, then a mix. How many coins each time?", notes: "10 dimes, 20 nickels. The mix invites quarters. Counting each set to 100 cents is the check.", ccss: "2.MD.C.8", grade: "2" },
    { title: "Change from 10", prompt: "An item costs 6 dollars and 40 cents. Pay with 10 dollars and show the change by counting up.", notes: "Counting up: 60 cents to 7 dollars, then 3 dollars to 10, change 3.60. The count-up method avoids borrowing errors.", ccss: "4.MD.A.2", grade: "4" },
    { title: "Coin values sort", prompt: "Lay out one of each coin. Order them by value and say each value in cents and dollars.", notes: "A dime is smaller in size but worth more than a nickel: value is not size. That misconception needs naming.", ccss: "2.MD.C.8", grade: "2" },
    { title: "Two ways to pay", prompt: "Pay 87 cents in two different ways. Which way would a shopkeeper prefer and why?", notes: "Fewer coins is usually preferred. Children should justify with coin counts, not just preference.", ccss: "2.MD.C.8", grade: "2" },
    { title: "Bill exchange", prompt: "Show 10 one-dollar bills, exchange for a ten. Then show 10 tens and exchange for a hundred. What pattern rules exchanges?", notes: "Ten of one bill makes the next, mirroring place value exactly. Naming the parallel is the learning goal.", ccss: "2.NBT.A.1", grade: "2" },
    { title: "Budget left over", prompt: "You have 15 dollars. Items cost 4 dollars 25, 5 dollars 50 and 3 dollars 75. Can you buy all three? Show the money work.", notes: "Total 13.50, so yes with 1.50 left. Showing leftover in coins forces exact decimal addition.", ccss: "4.MD.A.2", grade: "4" },
    { title: "Half dollar talk", prompt: "Build 50 cents four ways. Which way uses a single coin and what is that coin called?", notes: "The half dollar is one coin for 50 cents. Comparing ways shows coin choice is about efficiency.", ccss: "2.MD.C.8", grade: "2" },
    { title: "Price compare", prompt: "Two toys cost 7 dollars 99 and 8 dollars 5 cents. Build both amounts and say which costs more and by how much.", notes: "8.05 is more by 6 cents. The 99 cents traps children into thinking the first is more because 99 beats 5.", ccss: "4.NBT.A.2", grade: "4" },
    { title: "Saving goal", prompt: "You need 25 dollars. You have 17 dollars 50. How much more must you save? Show it in bills and coins.", notes: "7 dollars 50 more. Counting up from what you have to the goal is the natural method here.", ccss: "4.MD.A.2", grade: "4" },
    { title: "Quarter collection", prompt: "Collect quarters until you pass 2 dollars. How many quarters and what total did you land on?", notes: "8 quarters make exactly 2 dollars, so passing it needs 9 quarters, 2.25. The exact landing is a nice surprise to discuss.", ccss: "2.MD.C.8", grade: "2" },
    { title: "Decimal money write", prompt: "Build 3 dollars 7 cents. Write it as a decimal amount. Why is it 3.07 and not 3.7?", notes: "Seven cents is seven hundredths, needing the zero placeholder. Money is the friendliest decimal context for this idea.", ccss: "4.MD.A.2", grade: "4" },
    { title: "Make change challenge", prompt: "Cost is 2 dollars 35, paid with 5 dollars. Make the change using the fewest coins and bills possible.", notes: "Change 2.65: two dollars, two quarters, one dime, one nickel. Fewest-coins is an optimisation children enjoy.", ccss: "4.MD.A.2", grade: "4" },
  ],
  "algebra-tiles": [
    { title: "Zero pair clean up", prompt: "Build 2x - 3 + x + 5. Pair zeros and write the cleaned expression.", notes: "Pairs remove -3 with 3 of the 5, leaving 3x + 2. Cleaning before counting prevents sign slips.", ccss: "7.EE.A.1", grade: "7" },
    { title: "Distribute with tiles", prompt: "Build 3(x + 2) as three identical rows. Read the expanded form from the tiles.", notes: "Three rows each x + 2 give 3x + 6. Rows make distribution a copying action, not a rule to memorise.", ccss: "7.EE.A.1", grade: "7" },
    { title: "Equation balance", prompt: "Model 2x + 1 = 7. Use tiles to isolate x, keeping the two sides balanced at every step.", notes: "Remove 1 from both sides, split 6 into two groups for the two x tiles: x = 3. Balance language must accompany every move.", ccss: "8.EE.C.7", grade: "8" },
    { title: "Negative area talk", prompt: "Build (x - 1)(x + 3) in the area model. Which regions are negative and what is the final expression?", notes: "The -1 row creates negative regions: x squared + 2x - 3. Signed regions are the hard, valuable part of this model.", ccss: "HSA-APR.A.1", grade: "9" },
    { title: "Like terms sort", prompt: "Scatter tiles for 4x, 2x squared, 3 units and 1x squared. Group like terms and write the sum.", notes: "Only same shape and size group together: 3x squared + 4x + 3. Tiles make unlike terms visibly unlike.", ccss: "6.EE.A.3", grade: "6" },
    { title: "Solve with negatives", prompt: "Model x - 4 = 3. Add zero pairs or positive units to both sides to free x.", notes: "Adding 4 to both sides is the legal move the tiles enforce: x = 7. Taking away from one side only breaks the balance.", ccss: "7.EE.B.4", grade: "7" },
    { title: "Factor a negative", prompt: "Factor x squared - x - 6 into a rectangle. What are the side lengths and the signs on them?", notes: "Sides are (x - 3) and (x + 2). Negative unit tiles must fill the corner exactly, which checks the signs.", ccss: "HSA-SSE.B.3a", grade: "9" },
    { title: "Expression match", prompt: "Build x squared + 3x + 2 and (x + 1)(x + 2) as a rectangle. Show they are the same tiles.", notes: "Expansion and factoring are the same tiles read two ways. Children should physically rearrange between the two readings.", ccss: "HSA-APR.A.1", grade: "9" },
    { title: "Inequality tiles", prompt: "Model x + 2 > 5 with tiles on one side of a greater-than line. What values of x could work?", notes: "Tiles show the threshold x = 3, with greater values beyond. The boundary case is the discussion point.", ccss: "7.EE.B.4b", grade: "7" },
    { title: "Two variable terms", prompt: "Build 2x + 3y + x + y. Combine like terms and explain why x and y tiles cannot merge.", notes: "Different lengths mean different variables: 3x + 4y. Shape difference is the reason, not a rule.", ccss: "7.EE.A.1", grade: "7" },
    { title: "Square a binomial", prompt: "Build (x + 2) squared as a square array. Name each of the four regions and the total.", notes: "Regions x squared, 2x, 2x and 4 give x squared + 4x + 4. The two middle regions being equal surprises many learners.", ccss: "HSA-APR.A.1", grade: "9" },
    { title: "Equation from tiles", prompt: "A balance shows 3x on one side and 12 units on the other. Write and solve the equation.", notes: "Each x must be 4 units. Division appears as sharing the units equally among the x tiles.", ccss: "6.EE.B.7", grade: "6" },
  ],
  "xy-coordinate-board": [
    { title: "Reflections", prompt: "Plot (3, 2) and reflect it across the y-axis, then across the x-axis. Write all three points.", notes: "Reflections flip one sign at a time: (-3, 2) and (3, -2). The symmetry on the board makes sign rules memorable.", ccss: "8.G.A.1", grade: "8" },
    { title: "Line of points", prompt: "Plot points where y is always 2 more than x, for x from 0 to 5. What do the points do?", notes: "They form a straight line with rule y = x + 2. Children should predict the next point before plotting it.", ccss: "6.EE.C.9", grade: "6" },
    { title: "Distance on the grid", prompt: "Plot (1, 1) and (1, 6). How far apart are they? Now plot (2, 3) and (7, 3) and measure again.", notes: "Vertical distance 5, horizontal distance 5. Counting grid steps along one axis is the method at this stage.", ccss: "6.NS.C.8", grade: "6" },
    { title: "Quadrant sort", prompt: "Plot (-4, 5), (4, -5), (-4, -5) and (5, 4). Name the quadrant of each point.", notes: "One point per quadrant. Sign pairs decide quadrants: this is the core skill and the board makes it visual.", ccss: "6.NS.C.6b", grade: "6" },
    { title: "Shape translation", prompt: "Plot a triangle, then move every point 3 right and 2 up. Write the new points and describe the move.", notes: "Translations add to coordinates: (x + 3, y + 2). The shape does not turn or resize, which children should verify.", ccss: "8.G.A.1", grade: "8" },
    { title: "Table to graph", prompt: "A table shows (0, 1), (1, 3), (2, 5), (3, 7). Plot them and find the rule linking x and y.", notes: "Rule is y = 2x + 1. Plotting first often reveals the doubling pattern faster than staring at numbers.", ccss: "8.F.A.1", grade: "8" },
    { title: "Midpoint guess", prompt: "Plot (2, 2) and (6, 6). Find the point exactly halfway between them by eye, then check its coordinates.", notes: "Midpoint is (4, 4), the average of each coordinate. Averaging emerges naturally from the picture.", ccss: "6.NS.C.8", grade: "6" },
    { title: "Negative slope talk", prompt: "Plot (0, 6), (2, 4), (4, 2) and (6, 0). Describe the direction of the line and the pattern in y.", notes: "As x grows by 2, y falls by 2. Direction language (downhill) prepares for slope without formulas.", ccss: "8.F.B.4", grade: "8" },
    { title: "Area on the grid", prompt: "Plot a rectangle from (1, 1) to (5, 4). Count its width and height in units and find its area.", notes: "Width 4, height 3, area 12 square units. Coordinates give side lengths by subtraction.", ccss: "6.G.A.3", grade: "6" },
    { title: "Ordered pair story", prompt: "A point (4, 7) shows 4 hours and 7 kilometres. Plot more points for a walk and describe what the graph says.", notes: "Context stops plotting being mechanical. A flat section means resting, which children read eagerly.", ccss: "6.EE.C.9", grade: "6" },
    { title: "Symmetry points", prompt: "Plot (2, 5) and (8, 5). Where is the vertical line that would swap them? Plot a third point on that line.", notes: "The mirror line is x = 5, halfway between. Points on the line stay fixed under reflection.", ccss: "8.G.A.1", grade: "8" },
    { title: "First quadrant map", prompt: "In first quadrant only, plot a school at (2, 3), a park at (7, 3) and a shop at (7, 8). What route joins them with two straight moves?", notes: "Moves are horizontal then vertical, like city blocks. Route length is 5 + 5 = 10 units.", ccss: "5.G.A.2", grade: "5" },
  ],
  "geoboard": [
    { title: "Triangles of area 1", prompt: "Make a triangle with area exactly 1 square unit in two different ways. Prove each area by counting.", notes: "Right triangles covering half of a 2 by 1 rectangle work. Half-unit counting must be explicit.", ccss: "3.MD.C.6", grade: "3" },
    { title: "Isosceles hunt", prompt: "Make an isosceles triangle, then an equilateral attempt. What does the peg grid allow and not allow?", notes: "True equilateral triangles cannot be made on a square peg grid, a famous and discussable limitation.", ccss: "4.G.A.2", grade: "4" },
    { title: "Parallel bands", prompt: "Stretch two bands that never meet and two that cross. How do peg positions show parallel?", notes: "Parallel bands step across and up by the same pattern. Slope language can be introduced informally here.", ccss: "4.G.A.1", grade: "4" },
    { title: "Area by splitting", prompt: "Make a hexagon and split it into rectangles and triangles with extra bands. Add the parts for its area.", notes: "Splitting is the general area strategy. Any split that covers without overlap is valid, so compare methods.", ccss: "6.G.A.1", grade: "6" },
    { title: "Smallest perimeter", prompt: "Make a shape of area 3 with the smallest perimeter you can. Compare shapes with a partner.", notes: "Compact shapes win again: a 3 by 1 strip has perimeter 8, an L shape can match or differ, prompting careful counting.", ccss: "4.MD.A.3", grade: "4" },
    { title: "Angle sizes", prompt: "Make angles that look like 45 degrees, 90 degrees and 135 degrees between pegs. How can you check each?", notes: "Diagonals give 45 degrees on a square grid. Checking with a corner and a diagonal fold makes the estimates honest.", ccss: "4.MD.C.6", grade: "4" },
    { title: "Mirror shape", prompt: "Make a shape on the left half of the board, then mirror it on the right. What rule did your hands follow?", notes: "Each peg maps to the peg the same distance on the other side of the middle line. Distance language is the key.", ccss: "4.G.A.3", grade: "4" },
    { title: "Pentomino try", prompt: "Use bands to outline a shape of 5 square units in a P pentomino shape. Find another pentomino.", notes: "There are 12 free pentominoes. Hunting them on a geoboard is rich spatial work with a clear area check.", ccss: "3.MD.C.6", grade: "3" },
    { title: "Circle board fractions", prompt: "On the circular board, join the centre to pegs to show 1/4, 1/3 and 1/6 of a full turn.", notes: "Twelve pegs divide the turn into twelfths, so quarters are 3 pegs, thirds 4, sixths 2. Fractions of a turn become visible.", ccss: "4.MD.C.5", grade: "4" },
    { title: "Rectangle ratios", prompt: "Make rectangles 2 by 3 and 4 by 6. How are they alike and how do their areas compare?", notes: "Same shape, scaled: area grows from 6 to 24, four times, because both sides doubled. A key ratio insight.", ccss: "7.G.A.1", grade: "7" },
    { title: "Pick a perimeter", prompt: "Make a shape with perimeter exactly 12 units. Then make a different shape with the same perimeter but larger area.", notes: "Many shapes share perimeter 12; the 3 by 3 square encloses the most area at 9. Comparing areas settles arguments.", ccss: "4.MD.A.3", grade: "4" },
    { title: "Coordinates on pegs", prompt: "Label the bottom-left peg (0, 0). Give the coordinates of each corner of your shape and have a partner rebuild it from coordinates alone.", notes: "Rebuilding from coordinates alone tests precision. This bridges geoboard work to the coordinate board.", ccss: "5.G.A.1", grade: "5" },
  ],
  "pattern-blocks": [
    { title: "Trapezoid whole", prompt: "If a trapezoid is the whole, what fraction is one triangle and what fraction is the parallelogram?", notes: "Triangle is 1/3 of a trapezoid, parallelogram is 2/3. Changing the whole changes every fraction, which is the lesson.", ccss: "4.NF.A.1", grade: "4" },
    { title: "Build a larger hexagon", prompt: "Use trapezoids and triangles to build a hexagon twice the size of the yellow one. How many triangles would it take?", notes: "The larger hexagon is not a pattern block, so children compose it: worth discussing what counts as the whole now.", ccss: "5.NF.B.4", grade: "5" },
    { title: "Angle sums", prompt: "Put triangles around a point until they close the full turn. How many and what does that tell you about each angle?", notes: "Six triangle angles of 60 degrees close the turn. Angle as a fraction of a turn is the concept being built.", ccss: "4.MD.C.5", grade: "4" },
    { title: "Design with value", prompt: "Build a design worth exactly 2 hexagons using only trapezoids and parallelograms. Record your combination.", notes: "Many combinations reach 2, for example 2 trapezoids and 3 parallelograms. Requiring exact value adds arithmetic to design.", ccss: "4.NF.B.3", grade: "4" },
    { title: "Rhombus talk", prompt: "Compare the blue parallelogram and the tan rhombus. Both equal 2 triangles in area. How are their angles different?", notes: "Area equal does not mean shape equal. Naming the skinny and wide angles prepares for angle measurement.", ccss: "4.G.A.1", grade: "4" },
    { title: "Pattern train", prompt: "Build a train: hexagon, trapezoid, hexagon, trapezoid. Extend it to 10 blocks and count each shape.", notes: "Repeating units can be counted in pairs: 5 hexagons and 5 trapezoids in 10 blocks. Unit language matters.", ccss: "K.G.B.5", grade: "K" },
    { title: "Fill the outline", prompt: "Fill a large triangle outline using only triangles, then only parallelograms and triangles mixed. Which used fewer blocks?", notes: "Fewer larger blocks usually wins, but exact fit decides. Misfits should be kept visible as learning moments.", ccss: "1.G.A.2", grade: "1" },
    { title: "Thirds in three ways", prompt: "Show 1/3 of a hexagon using a parallelogram, using 2 triangles, and using part of a trapezoid design. Explain each.", notes: "One whole, three representations of a third. Equivalence across shapes is deeper than within one shape.", ccss: "3.NF.A.3b", grade: "3" },
    { title: "Square from blocks", prompt: "Combine blocks to form a square shape. Which blocks did you use and what is the square worth in triangles?", notes: "A square block plus triangles can compose larger squares. Worth-in-triangles gives a common measure.", ccss: "2.G.A.1", grade: "2" },
    { title: "Deci blocks link", prompt: "In the Deci workspace, if the hexagon is 1, what decimal is a triangle? Build 0.5 two ways.", notes: "A triangle is one sixth, not a tidy decimal, which sparks honest discussion about which wholes give tidy decimals.", ccss: "5.NBT.A.3", grade: "5" },
    { title: "Border a hexagon", prompt: "Ring a hexagon with a border of squares. How many squares and do the corners fit exactly?", notes: "Squares do not share hexagon angles neatly, so gaps appear. Angle mismatch is discoverable, not a failure.", ccss: "4.G.A.1", grade: "4" },
    { title: "Invent a whole", prompt: "Choose the parallelogram as the whole. Rebuild a hexagon and say its value in this new system.", notes: "The hexagon is worth 3 parallelograms. Renaming the whole revalues everything, the essence of unit fractions.", ccss: "3.NF.A.1", grade: "3" },
  ],
  "clock": [
    { title: "Quarter past journey", prompt: "Set the clock to quarter past 3, then move forward quarter of an hour at a time until 5 o'clock. List every time you pass.", notes: "Times run 3:15, 3:30, 3:45, 4:00 and on to 5:00. Quarter steps tile the hour exactly four times.", ccss: "2.MD.C.7", grade: "2" },
    { title: "Minutes to noon", prompt: "Set the clock to 11:35. How many minutes until noon? Show the jump on the time bar.", notes: "25 minutes, found by counting by fives to 12. The minute hand positions 7 means 35 minutes, not 7.", ccss: "3.MD.A.1", grade: "3" },
    { title: "Hour hand creep", prompt: "Set 6:00, then 6:30, then 6:55. Describe where the hour hand points each time and why.", notes: "The hour hand moves halfway by 6:30 and nearly reaches 7 by 6:55. Creep is proportional, which children can state in their own words.", ccss: "2.MD.C.7", grade: "2" },
    { title: "Backwards time", prompt: "Start at 4:20 and move back 35 minutes. Where do you land and how did you cross the hour?", notes: "Landing is 3:45. Crossing the hour backwards is the hard step; bridge through 4:00 explicitly.", ccss: "3.MD.A.1", grade: "3" },
    { title: "Digital mismatch", prompt: "A digital clock says 7:05 but an analogue clock shows the minute hand on the 1. Are they showing the same time? Explain.", notes: "Yes: the 1 means 5 minutes. The number on the face is hours for one hand and five-minute steps for the other.", ccss: "2.MD.C.7", grade: "2" },
    { title: "Half hour intervals", prompt: "Use the tracker to add 30 minutes six times from 9:00. Where do you land and how many hours passed?", notes: "Six halves make 3 hours, landing at 12:00. Grouping halves into hours is the strategy.", ccss: "3.MD.A.1", grade: "3" },
    { title: "School day timeline", prompt: "Set clocks for school start 8:45 and home time 3:15. How long is the school day?", notes: "6 hours 30 minutes, bridged through 12:00. Two clocks keep both ends of the problem visible.", ccss: "3.MD.A.1", grade: "3" },
    { title: "Five minutes to", prompt: "Set ten to 5, then five to 5. Write both in digital form and explain the to language.", notes: "4:50 and 4:55. To times name the coming hour, which is why the hour hand nearly touches 5.", ccss: "2.MD.C.7", grade: "2" },
    { title: "Interval wedge", prompt: "Set the hands to show a 40 minute interval starting at 2:10. Where is the end hand and what time is it?", notes: "End is 2:50. The wedge between hands is the interval, making duration a visible slice.", ccss: "3.MD.A.1", grade: "3" },
    { title: "AM PM talk", prompt: "Set 7:30. Tell two stories, one morning and one evening, that fit this time. What extra letters does digital time need?", notes: "AM and PM disambiguate the twice-daily times. Stories make the need for the labels obvious.", ccss: "2.MD.C.7", grade: "2" },
    { title: "Race the minute hand", prompt: "How many times does the minute hand lap the hour hand between 12:00 and 1:00? Watch the geared hands and reason it out.", notes: "The minute hand passes the hour hand once in that hour, just after 1:05 in the next hour cycle discussion. Reasoning matters more than the count.", ccss: "3.MD.A.1", grade: "3" },
    { title: "Plan a morning", prompt: "You wake at 6:45, need 20 minutes to eat and 15 minutes to travel. Set each clock stage and find your arrival time.", notes: "Stages land at 7:05 and 7:20. Sequencing intervals is real elapsed-time planning.", ccss: "3.MD.A.1", grade: "3" },
  ],
};